// ============================================================
// KONFIGURER DISSE – bytt ut til dine Mac-stier
// ============================================================
const SCRIPT_PATH  = "/Users/YOURNAME/ComfyUI/script/pre/render-title.py";
const IMAGE_PATH   = "/Users/YOURNAME/ComfyUI/input/frontpage_bg.png";
const OUT_DIR      = "/Users/YOURNAME/ComfyUI/output/title_tests";

// Bytt ut python3 med full sti om nødvendig, f.eks:
// "/usr/bin/python3" eller din venv: "/Users/YOURNAME/venv/bin/python3"
const PYTHON       = "python3";

// Tekst
const LINE1        = "MIN BOK";
const LINE2        = "UNDERTITTEL";

// Typografi
const TOP_MARGIN   = 0.05;
const LINE_SPACING = 0.01;
const FONT_SMALL   = 80;
const FONT_LARGE   = 140;

// ============================================================
// FARGEPRESET
// gold:   "R,G,B"         → flat farge
//         "R,G,B,R,G,B"   → gradient (topp → bunn)
// shadow: "R,G,B"
// ============================================================
const colorPresets = [
  { name: "gull_klassisk",   gold: "212,175,55",               shadow: "5,5,5"    },
  { name: "gull_varm",       gold: "255,215,0,180,130,20",     shadow: "20,10,0"  },
  { name: "gull_brent",      gold: "200,140,20,140,80,0",      shadow: "20,8,0"   },
  { name: "hvit",            gold: "255,255,255",               shadow: "0,0,0"    },
  { name: "krem",            gold: "255,250,220",               shadow: "10,8,5"   },
  { name: "solv",            gold: "220,220,220,160,160,160",  shadow: "5,5,5"    },
  { name: "rose_gold",       gold: "255,190,152,200,120,80",   shadow: "60,20,10" },
  { name: "himmelblaa",      gold: "100,160,255,50,90,210",    shadow: "5,10,30"  },
  { name: "dyp_rod",         gold: "220,50,50,150,20,20",      shadow: "20,0,0"   },
  { name: "skogsgronn",      gold: "80,180,100,30,120,50",     shadow: "0,15,5"   },
  { name: "lys_lilla",       gold: "200,160,255,140,80,220",   shadow: "20,0,40"  },
  { name: "svart",           gold: "30,30,30",                  shadow: "0,0,0"    },
];

// ============================================================
// Bygg ett item per farge (n8n kjorer Execute Command en gang per item)
// ============================================================
return colorPresets.map(preset => {
  const outPath = `${OUT_DIR}/title_${preset.name}.png`;

  const command = [
    PYTHON,
    `"${SCRIPT_PATH}"`,
    `--image "${IMAGE_PATH}"`,
    `--out "${outPath}"`,
    `--line1 "${LINE1}"`,
    `--line2 "${LINE2}"`,
    `--top_margin ${TOP_MARGIN}`,
    `--line_spacing ${LINE_SPACING}`,
    `--font_small ${FONT_SMALL}`,
    `--font_large ${FONT_LARGE}`,
    `--gold "${preset.gold}"`,
    `--shadow "${preset.shadow}"`,
  ].join(' ');

  return {
    json: {
      name:    preset.name,
      command,
      out_path: outPath,
    }
  };
});

// Skriv ut hvilke filer som ble lagret
const items = $input.all();
const results = items.map(item => ({
  json: {
    fil:    item.json.name || '?',
    stdout: (item.json.stdout || '').trim(),
    stderr: (item.json.stderr || '').trim(),
    ok:     !(item.json.stderr || '').trim(),
  }
}));
return results;
